class EmployeeManagementSystem {
  constructor() {
    this.employees = [];
    this.attendanceRecords = [];
    this.initializeApp();
  }

  initializeApp() {
    // Initialize with sample data
    this.loadSampleData();
    this.renderDashboard();
    this.setupEventListeners();
  }

  loadSampleData() {
    // Sample employee data
    this.employees = [
