  updateEmployee(id, updatedData) {
    const employeeIndex = this.employees.findIndex(emp => emp.id === id);
    if (employeeIndex !== -1) {
      this.employees[employeeIndex] = { ...this.employees[employeeIndex], ...updatedData };
      return this.employees[employeeIndex];
