    "styles.css": "@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');\n\n:root {\n  --primary-color: #2563eb;\n  --primary-dark: #1d4ed8;\n  --secondary-color: #0f172a;\n  --accent-color: #8b5cf6;\n  --success-color: #10b981;\n  --warning-color: #f59e0b;\n  --error-color: #ef4444;\n  --light-color: #f8fafc;\n  --dark-color: #0f172a;\n  --gray-100: #f1f5f9;\n  --gray-200: #e2e8f0;\n  --gray-300: #cbd5e1;\n  --gray-400: #94a3b8;\n  --gray-500: #64748b;\n  --gray-600: #475569;\n  --gray-700: #334155;\n  --gray-800: #1e293b;\n  --border-radius: 8px;\n  --box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);\n  --transition: all 0.3s ease;\n}\n\n* {\n  margin: 0;\n  padding: 0;\n  box-sizing: border-box;\n}\n\nbody {\n  font-family: 'Inter', sans-serif;\n  background-color: var(--light-color);\n  color: var(--dark-color);\n  line-height: 1.6;\n}\n\n.container {\n  width: 100%;\n  max-width: 1200px;\n  margin: 0 auto;\n  padding: 0 1rem;\n}\n\n/* Header Styles */\n.header {\n  background-color: var(--secondary-color);\n  color: white;\n  padding: 1rem 0;\n  box-shadow: var(--box-shadow);\n  position: sticky;\n  top: 0;\n  z-index: 100;\n}\n\n.header-content {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n}\n\n.logo {\n  font-size: 1.5rem;\n  font-weight: 700;\n}\n\n.nav-menu {\n  display: flex;\n  list-style: none;\n  gap: 1rem;\n}\n\n.nav-link {\n  color: white;\n  text-decoration: none;\n  padding: 0.5rem 1rem;\n  border-radius: var(--border-radius);\n  transition: var(--transition);\n}\n\n.nav-link:hover {\n  background-color: rgba(255, 255, 255, 0.1);\n}\n\n/* Dashboard Grid */\n.dashboard-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));\n  gap: 1.5rem;\n  margin-top: 2rem;\n}\n\n.card {\n  background-color: white;\n  border-radius: var(--border-radius);\n  box-shadow: var(--box-shadow);\n  padding: 1.5rem;\n  transition: var(--transition);\n}\n\n.card:hover {\n  transform: translateY(-5px);\n  box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);\n}\n\n.card-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin-bottom: 1rem;\n}\n\n.card-title {\n  font-size: 1.25rem;\n  font-weight: 600;\n  color: var(--secondary-color);\n}\n\n/* Form Styles */\n.form-container {\n  background-color: white;\n  border-radius: var(--border-radius);\n  box-shadow: var(--box-shadow);\n  padding: 2rem;\n  margin-top: 2rem;\n}\n\n.form-group {\n  margin-bottom: 1.5rem;\n}\n\n.form-label {\n  display: block;\n  margin-bottom: 0.5rem;\n  font-weight: 500;\n  color: var(--secondary-color);\n}\n\n.form-input,\n.form-select,\n.form-textarea {\n  width: 100%;\n  padding: 0.75rem;\n  border: 1px solid var(--gray-300);\n  border-radius: var(--border-radius);\n  font-family: 'Inter', sans-serif;\n  font-size: 1rem;\n  transition: var(--transition);\n}\n\n.form-input:focus,\n.form-select:focus,\n.form-textarea:focus {\n  outline: none;\n  border-color: var(--primary-color);\n  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.1);\n}\n\n.form-textarea {\n  min-height: 120px;\n  resize: vertical;\n}\n\n.btn {\n  padding: 0.75rem 1.5rem;\n  border: none;\n  border-radius: var(--border-radius);\n  font-family: 'Inter', sans-serif;\n  font-size: 1rem;\n  font-weight: 500;\n  cursor: pointer;\n  transition: var(--transition);\n}\n\n.btn-primary {\n  background-color: var(--primary-color);\n  color: white;\n}\n\n.btn-primary:hover {\n  background-color: var(--primary-dark);\n}\n\n.btn-secondary {\n  background-color: var(--gray-200);\n  color: var(--secondary-color);\n}\n\n.btn-secondary:hover {\n  background-color: var(--gray-300);\n}\n\n/* Table Styles */\n.table-container {\n  background-color: white;\n  border-radius: var(--border-radius);\n  box-shadow: var(--box-shadow);\n  overflow: hidden;\n  margin-top: 2rem;\n}\n\n.table {\n  width: 100%;\n  bor