r {\n  background-color: rgba(239, 68, 68, 0.1);\n  color: var(--error-color);\n  border-left: 4px solid var(--error-color);\n}\n\n.alert-warning {\n  background-color: rgba(245, 158, 11, 0.1);\n  color: var(--warning-color);\n  border-left: 4px solid var(--warning-color);\n}\n\n/* Pagination */\n.pagination {\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  gap: 0.5rem;\n  margin-top: 2rem;\n}\n\n.page-btn {\n  padding: 0.5rem 1rem;\n  border: 1px solid var(--gray-300);\n  background-color: white;\n  border-radius: var(--border-radius);\n  cursor: pointer;\n  transition: var(--transition);\n}\n\n.page-btn:hover {\n  background-color: var(--gray-100);\n}\n\n.page-btn.active {\n  background-color: var(--primary-color);\n  color: white;\n  border-color: var(--primary-color);\n}\n\n/* Dashboard Stats */\n.stats-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\n  gap: 1rem;\n  margin-top: 2rem;\n}\n\n.stat-card {\n  background-color: white;\n  border-radius: var(--border-radius);\n  box-shadow: var(--box-shadow);\n  padding: 1.5rem;\n  text-align: center;\n}\n\n.stat-value {\n  font-size: 2rem;\n  font-weight: 700;\n  margin-bottom: 0.5rem;\n}\n\n.stat-label {\n  color: var(--gray-600);\n  font-size: 0.875rem;\n}\n\n/* Employee Profile */\n.employee-profile {\n  display: flex;\n  gap: 2rem;\n  margin-top: 2rem;\n}\n\n.profile-avatar {\n  width: 120px;\n  height: 120px;\n  border-radius: 50%;\n  object-fit: cover;\n  border: 4px solid var(--gray-200);\n}\n\n.profile-info {\n  flex: 1;\n}\n\n.profile-name {\n  font-size: 1.5rem;\n  font-weight: 700;\n  margin-bottom: 0.5rem;\n}\n\n.profile-title {\n  color: var(--gray-600);\n  margin-bottom: 1rem;\n}\n\n.profile-details {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\n  gap: 1rem;\n}\n\n.detail-item {\n  display: flex;\n  flex-direction: column;\n}\n\n.detail-label {\n  font-size: 0.875rem;\n  color: var(--gray-500);\n}\n\n