    "index.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>HRMS Application</title>\n  <link href=\"https://cdn.jsdelivr.net/npm/tailwindcss@2.2.19/dist/tailwind.min.css\" rel=\"stylesheet\">\n</head>\n<body class=\"bg-gray-100\">\n  <div id=\"root\" class=\"min-h-screen flex flex-col\">\n    <!-- Header -->\n    <header class=\"bg-blue-600 text-white shadow-md\">\n      <div class=\"container mx-auto px-4 py-3 flex justify-between items-center\">\n        <h1 class=\"text-xl font-bold\">Human Resource Management System</h1>\n        <nav>\n          <ul class=\"flex space-x-4\">\n            <li><a href=\"#\" class=\"hover:underline\">Dashboard</a></li>\n            <li><a href=\"#\" class=\"hover:underline\">Employees</a></li>\n            <li><a href=\"#\" class=\"hover:underline\">Departments</a></li>\n            <li><a href=\"#\" class=\"hover:underline\">Reports</a></li>\n            <li><a href=\"#\" class=\"hover:underline\">Settings</a></li>\n          </ul>\n        </nav>\n      </div>\n    </header>\n\n    <!-- Main Content -->\n    <main class=\"flex-grow container mx-auto px-4 py-6\">\n      <div class=\"bg-white rounded-lg shadow-md p-6 mb-6\">\n        <h2 class=\"text-2xl font-semibold text-gray-800 mb-4\">Welcome to HRMS</h2>\n        <p class=\"text-gray-600 mb-4\">Manage your organization's human resources efficiently with our comprehensive HR management system.</p>\n        \n        <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4 mt-6\">\n          <div class=\"bg-blue-50 p-4 rounded-lg border border-blue-100\">\n            <h3 class=\"font-medium text-blue-800 mb-2\">Employee Management</h3>\n            <p class=\"text-sm text-gray-600\">Add, update, and manage employee records and information.</p>\n          </div>\n          \n          <div class=\"bg-green-50 p-4 rounded-lg border border-green-100\">\n            <h3 class=\"font-medium text-green-800 mb-2\">Payroll Processing</h3>\n            <p class=\"text-sm text-gray-600\">Calculate and process employee salaries and benefits.</p>\n          </div>\n          \n          <div class=\"bg-purple-50 p-4 rounded-lg border border-purple-100\">\n            <h3 class=\"font-medium text-purple-800 mb-2\">Leave Management</h3>\n            <p class=\"text-sm text-gray-600\">Track and approve employee leave requests.</p>\n          </div>\n        </div>\n      </div>\n\n      <!-- Stats Section -->\n      <div class=\"grid grid-cols-1 md:grid-cols-4 gap-4 mb-6\">\n        <div class=\"bg-white p-4 rounded-lg shadow\">\n          <p class=\"text-gray-500 text-sm\">Total Employees</p>\n          <p class=\"text-2xl font-bold\">1,248</p>\n        </div>\n        \n        <div class=\"bg-white p-4 rounded-lg shadow\">\n          <p class=\"text-gray-500 text-sm\">Active Departments</p>\n          <p class=\"text-2xl font-bold\">12</p>\n        </div>\n        \n        <div class=\"bg-white p-4 rounded-lg shadow\">\n          <p class=\"text-gray-500 text-sm\">Pending Leave Requests</p>\n          <p class=\"text-2xl font-bold\">23</p>\n        </div>\n        \n        <div class=\"bg-white p-4 rounded-lg shadow\">\n          <p class=\"text-gray-500 text-sm\">New Hires (This Month)</p>\n          <p class=\"text-2xl font-bold\">12</p>\n        </div>\n      </div>\n\n      <!-- Recent Activity -->\n      <div class=\"bg-white rounded-lg shadow-md p-6\">\n        <h3 class=\"text-lg font-semibold text-gray-800 mb-4\">Recent Activity</h3>\n        <ul class=\"space-y-3\">\n          <li class=\"flex items-start border-b pb-3\">\n            <div class=\"bg-blue-100 rounded-full p-2 mr-3\">\n              <svg xmlns=\"http://www.w3.org/2000/svg\" class=\"h-5 w-5 text-blue-600\" viewBox=\"0 0 20 20\" fill=\"currentColor\">\n                <path fill-rule=\"evenodd\" d=\"M10 18a8 8 0 100-16 8 8 0 000 16zm1-11a1 1 0 10-2 0v2H7a1 1 0 100 2h2v2a1 1 0 102 0v-2h2a1 1 0 100-2h-2V7z\" clip-rule=\"evenodd\" />\n              </svg>\n            </div>\n            <div>\n              <p class=\"font-medium\">New employee added</p>\n              <p class=\"text-sm text-gray-500\">John Smith joined the Marketing department</p>\n              <p class=\"text-xs text-gray-400\">2 hours ago</p>\n            </div>\n          </li>\n          \n          <li class=\"flex items-start border-b pb-3\">\n            <div class=\"bg-green-100 rounded-full p-2 mr-3\">\n              <svg xmlns=\"http://www.w3.org/2000/svg\" class=\"h-5 w-5 text-green-600\" viewBox=\"0 0 20 20\" fill=\"currentColor\">\n                <path fill-rule=\"evenodd\" d=\"M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z\" clip-rule=\"evenodd\" />\n              </svg>\n            </div>\n            <div>\n              <p class=\"font-medium\">Leave approved</p>\n              <p class=\"text-sm text-gray-500\">Sarah Johnson's vacation request approved</p>\n              <p class=\"text-xs text-gray-400\">5 hours ago</p>\n            </div>\n          </li>\n          \n          <li class=\"flex items-start\">\n            <div class=\"bg-yellow-100 rounded-full p-2 mr-3\">\n              <svg xmlns=\"http://www.w3.org/2000/svg\" class=\"h-5 w-5 text-yellow-600\" viewBox=\"0 0 20 20\" fill=\"currentColor\">\n                <path d=\"M10 12a2 2 0 100-4 2 2 0 000 4z\" />\n                <path fill-rule=\"evenodd\" d=\"M.458 10C1.732 5.943 6.615 3 12 3s10.268 2.943 11.542 7c-1.274 4.057-6.156 7-11.542 7S1.732 14.057.458 10zM14 10a2 2 0 11-4 0 2 2 0 014 0z\" clip-rule=\"evenodd\" />\n              </svg>\n            </div>\n            <div>\n              <p class=\"font-medium\">Performance review due</p>\n              <p class=\"text-sm text-gray-500\">Monthly performance reviews are due for all employees</p>\n              <p class=\"text-xs text-gray-400\">1 day ago</p>\n            </div>\n          </li>\n        </ul>\n      </div>\n    </main>\n\n    <!-- Footer -->\n    <footer class=\"bg-gray-800 text-white py-6\">\n      <div class=\"container mx-auto px-4 text-center\">\n        <p>&copy; 2023 Human Resource Management System. All rights reserved.</p>\n      </div>\n    </footer>\n  </div>\n</body>\n</html>",
    "styles.css": "@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');\n\n:root {\n  --primary-color: #2563eb;\n  --primary-dark: #1d4ed8;\n  --secondary-color: #0f172a;\n  --accent-color: #8b5cf6;\n  --success-color: #10b981;\n  --warning-color: #f59e0b;\n  --error-color: #ef4444;\n  --light-color: #f8fafc;\n  --dark-color: #0f172a;\n  --gray-100: #f1f5f9;\n  --gray-200: #e2e8f0;\n  --gray-300: #cbd5e1;\n  --gray-400: #94a3b8;\n  --gray-500: #64748b;\n  --gray-600: #475569;\n  --gray-700: #334155;\n  --gray-800: #1e293b;\n  --border-radius: 8px;\n  --box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);\n  --transition: all 0.3s ease;\n}\n\n* {\n  margin: 0;\n  padding: 0;\n  box-sizing: border-box;\n}\n\nbody {\n  font-family: 'Inter', sans-serif;\n  background-color: var(--light-color);\n  color: var(--dark-color);\n  line-height: 1.6;\n}\n\n.container {\n  width: 100%;\n  max-width: 1200px;\n  margin: 0 auto;\n  padding: 0 1rem;\n}\n\n/* Header Styles */\n.header {\n  background-color: var(--secondary-color);\n  color: white;\n  padding: 1rem 0;\n  box-shadow: var(--box-shadow);\n  position: sticky;\n  top: 0;\n  z-index: 100;\n}\n\n.header-content {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n}\n\n.logo {\n  font-size: 1.5rem;\n  font-weight: 700;\n}\n\n.nav-menu {\n  display: flex;\n  list-style: none;\n  gap: 1rem;\n}\n\n.nav-link {\n  color: white;\n  text-decoration: none;\n  padding: 0.5rem 1rem;\n  border-radius: var(--border-radius);\n  transition: var(--transition);\n}\n\n.nav-link:hover {\n  background-color: rgba(255, 255, 255, 0.1);\n}\n\n/* Dashboard Grid */\n.dashboard-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));\n  gap: 1.5rem;\n  margin-top: 2rem;\n}\n\n.card {\n  background-color: white;\n  border-radius: var(--border-radius);\n  box-shadow: var(--box-shadow);\n  padding: 1.5rem;\n  transition: var(--transition);\n}\n\n.card:hover {\n  transform: translateY(-5px);\n  box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);\n}\n\n.card-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin-bottom: 1rem;\n}\n\n.card-title {\n  font-size: 1.25rem;\n  font-weight: 600;\n  color: var(--secondary-color);\n}\n\n/* Form Styles */\n.form-container {\n  background-color: white;\n  border-radius: var(--border-radius);\n  box-shadow: var(--box-shadow);\n  padding: 2rem;\n  margin-top: 2rem;\n}\n\n.form-group {\n  margin-bottom: 1.5rem;\n}\n\n.form-label {\n  display: block;\n  margin-bottom: 0.5rem;\n  font-weight: 500;\n  color: var(--secondary-color);\n}\n\n.form-input,\n.form-select,\n.form-textarea {\n  width: 100%;\n  padding: 0.75rem;\n  border: 1px solid var(--gray-300);\n  border-radius: var(--border-radius);\n  font-family: 'Inter', sans-serif;\n  font-size: 1rem;\n  transition: var(--transition);\n}\n\n.form-input:focus,\n.form-select:focus,\n.form-textarea:focus {\n  outline: none;\n  border-color: var(--primary-color);\n  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.1);\n}\n\n.form-textarea {\n  min-height: 120px;\n  resize: vertical;\n}\n\n.btn {\n  padding: 0.75rem 1.5rem;\n  border: none;\n  border-radius: var(--border-radius);\n  font-family: 'Inter', sans-serif;\n  font-size: 1rem;\n  font-weight: 500;\n  cursor: pointer;\n  transition: var(--transition);\n}\n\n.btn-primary {\n  background-color: var(--primary-color);\n  color: white;\n}\n\n.btn-primary:hover {\n  background-color: var(--primary-dark);\n}\n\n.btn-secondary {\n  background-color: var(--gray-200);\n  color: var(--secondary-color);\n}\n\n.btn-secondary:hover {\n  background-color: var(--gray-300);\n}\n\n/* Table Styles */\n.table-container {\n  background-color: white;\n  border-radius: var(--border-radius);\n  box-shadow: var(--box-shadow);\n  overflow: hidden;\n  margin-top: 2rem;\n}\n\n.table {\n  width: 100%;\n  border-collapse: collapse;\n}\n\n.table th,\n.table td {\n  padding: 1rem;\n  text-align: left;\n  border-bottom: 1px solid var(--gray-200);\n}\\n\n.table th {\n  background-color: var(--gray-100);\n  font-weight: 600;\n  color: var(--secondary-color);\n}\n\n.table tr:hover {\n  background-color: var(--gray-50);\n}\n\n/* Responsive Design */\n@media (max-width: 768px) {\n  .header-content {\n    flex-direction: column;\n    gap: 1rem;\n  }\n\n  .nav-menu {\n    flex-wrap: wrap;\n    justify-content: center;\n  }\n\n  .dashboard-grid {\n    grid-template-columns: 1fr;\n  }\n\n  .form-container {\n    padding: 1.5rem;\n  }\n\n  .table-container {\n    overflow-x: auto;\n  }\n}\n\n@media (max-width: 480px) {\n  .container {\n    padding: 0 0.5rem;\n  }\n\n  .card {\n    padding: 1rem;\n  }\n\n  .form-container {\n    padding: 1rem;\n  }\n\n  .btn {\n    width: 100%;\n    margin-bottom: 0.5rem;\n  }\n}\n\n/* Status Badges */\n.status-badge {\n  padding: 0.25rem 0.75rem;\n  border-radius: 9999px;\n  font-size: 0.875rem;\n  font-weight: 500;\n}\n\n.status-active {\n  background-color: rgba(16, 185, 129, 0.1);\n  color: var(--success-color);\n}\n\n.status-inactive {\n  background-color: rgba(239, 68, 68, 0.1);\n  color: var(--error-color);\n}\n\n.status-pending {\n  background-color: rgba(245, 158, 11, 0.1);\n  color: var(--warning-color);\n}\n\n/* Progress Bar */\n.progress-container {\n  width: 100%;\n  height: 8px;\n  background-color: var(--gray-200);\n  border-radius: 9999px;\n  overflow: hidden;\n}\n\n.progress-bar {\n  height: 100%;\n  background-color: var(--primary-color);\n  border-radius: 9999px;\n  transition: width 0.3s ease;\n}\n\n/* Alert Messages */\n.alert {\n  padding: 1rem;\n  border-radius: var(--border-radius);\n  margin-bottom: 1rem;\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n}\n\n.alert-success {\n  background-color: rgba(16, 185, 129, 0.1);\n  color: var(--success-color);\n  border-left: 4px solid var(--success-color);\n}\n\n.alert-error {\n  background-color: rgba(239, 68, 68, 0.1);\n  color: var(--error-color);\n  border-left: 4px solid var(--error-color);\n}\n\n.alert-warning {\n  background-color: rgba(245, 158, 11, 0.1);\n  color: var(--warning-color);\n  border-left: 4px solid var(--warning-color);\n}\n\n/* Pagination */\n.pagination {\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  gap: 0.5rem;\n  margin-top: 2rem;\n}\n\n.page-btn {\n  padding: 0.5rem 1rem;\n  border: 1px solid var(--gray-300);\n  background-color: white;\n  border-radius: var(--border-radius);\n  cursor: pointer;\n  transition: var(--transition);\n}\n\n.page-btn:hover {\n  background-color: var(--gray-100);\n}\n\n.page-btn.active {\n  background-color: var(--primary-color);\n  color: white;\n  border-color: var(--primary-color);\n}\n\n/* Dashboard Stats */\n.stats-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\n  gap: 1rem;\n  margin-top: 2rem;\n}\n\n.stat-card {\n  background-color: white;\n  border-radius: var(--border-radius);\n  box-shadow: var(--box-shadow);\n  padding: 1.5rem;\n  text-align: center;\n}\n\n.stat-value {\n  font-size: 2rem;\n  font-weight: 700;\n  margin-bottom: 0.5rem;\n}\n\n.stat-label {\n  color: var(--gray-600);\n  font-size: 0.875rem;\n}\n\n/* Employee Profile */\n.employee-profile {\n  display: flex;\n  gap: 2rem;\n  margin-top: 2rem;\n}\n\n.profile-avatar {\n  width: 120px;\n  height: 120px;\n  border-radius: 50%;\n  object-fit: cover;\n  border: 4px solid var(--gray-200);\n}\n\n.profile-info {\n  flex: 1;\n}\n\n.profile-name {\n  font-size: 1.5rem;\n  font-weight: 700;\n  margin-bottom: 0.5rem;\n}\n\n.profile-title {\n  color: var(--gray-600);\n  margin-bottom: 1rem;\n}\n\n.profile-details {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\n  gap: 1rem;\n}\n\n.detail-item {\n  display: flex;\n  flex-direction: column;\n}\n\n.detail-label {\n  font-size: 0.875rem;\n  color: var(--gray-500);\n}\n\n.detail-value {\n  font-weight: 500;\n}",
    "app.js": "class EmployeeManagementSystem {\n  constructor() {\n    this.employees = [];\n    this.attendanceRecords = [];\n    this.initializeApp();\n  }\n\n  initializeApp() {\n    // Initialize with sample data\n    this.loadSampleData();\n    this.renderDashboard();\n    this.setupEventListeners();\n  }\n\n  loadSampleData() {\n    // Sample employee data\n    this.employees = [\n      { id: 1, name: 'John Doe', position: 'Software Engineer', department: 'Engineering', email: 'john.doe@company.com' },\n      { id: 2, name: 'Jane Smith', position: 'Product Manager', department: 'Product', email: 'jane.smith@company.com' },\n      { id: 3, name: 'Robert Johnson', position: 'UX Designer', department: 'Design', email: 'robert.johnson@company.com' }\n    ];\n\n    // Sample attendance records\n    this.attendanceRecords = [\n      { id: 1, employeeId: 1, date: '2023-05-01', status: 'present', checkIn: '09:00', checkOut: '17:30' },\n      { id: 2, employeeId: 2, date: '2023-05-01', status: 'present', checkIn: '08:45', checkOut: '17:15' },\n      { id: 3, employeeId: 3, date: '2023-05-01', status: 'absent', checkIn: null, checkOut: null }\n    ];\n  }\n\n  setupEventListeners() {\n    // Setup event listeners for dashboard interactions\n    document.getElementById('addEmployeeBtn')?.addEventListener('click', () => this.showAddEmployeeForm());\n    document.getElementById('viewAttendanceBtn')?.addEventListener('click', () => this.renderAttendanceView());\n    document.getElementById('viewEmployeesBtn')?.addEventListener('click', () => this.renderEmployeeListView());\n  }\n\n  // API-001: Get all employees\n  getEmployees() {\n    return this.employees;\n  }\n\n  // API-002: Get employee by ID\n  getEmployeeById(id) {\n    return this.employees.find(emp => emp.id === id);\n  }\n\n  // API-003: Add new employee\n  addEmployee(employeeData) {\n    const newEmployee = {\n      id: this.generateId(),\n      ...employeeData\n    };\n    this.employees.push(newEmployee);\n    return newEmployee;\n  }\n\n  // API-004: Update employee information\n  updateEmployee(id, updatedData) {\n    const employeeIndex = this.employees.findIndex(emp => emp.id === id);\n    if (employeeIndex !== -1) {\n      this.employees[employeeIndex] = { ...this.employees[employeeIndex], ...updatedData };\n      return this.employees[employeeIndex];\n    }\n    return null;\n  }\n\n  // API-005: Delete employee\n  deleteEmployee(id) {\n    const employeeIndex = this.employees.findIndex(emp => emp.id === id);\n    if (employeeIndex !== -1) {\n      this.employees.splice(employeeIndex, 1);\n      return true;\n    }\n    return false;\n  }\n\n  // API-006: Get attendance records\n  getAttendanceRecords() {\n    return this.attendanceRecords;\n  }\n\n  // API-007: Add attendance record\n  addAttendanceRecord(recordData) {\n    const newRecord = {\n      id: this.generateId(),\n      ...recordData\n    };\n    this.attendanceRecords.push(newRecord);\n    return newRecord;\n  }\n\n  generateId() {\n    return Math.max(0, ...this.employees.map(emp => emp.id), ...this.attendanceRecords.map(record => record.id)) + 1;\n  }\n\n  renderDashboard() {\n    const dashboard = document.getElementById('dashboard');\n    if (!dashboard) return;\n\n    const employeeCount = this.employees.length;\n    const presentCount = this.attendanceRecords.filter(record => record.status === 'present').length;\n    const absentCount = this.attendanceRecords.filter(record => record.status === 'absent').length;\n\n    dashboard.innerHTML = `\n      <div class=\"p-6 bg-white rounded-lg shadow-md\">\n        <h2 class=\"text-2xl font-bold text-gray-800 mb-4\">Employee Dashboard</h2>\n        \n        <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4 mb-6\">\n          <div class=\"bg-blue-50 p-4 rounded-lg\">\n            <h3 class=\"text-lg font-semibold text-blue-800\">Total Employees</h3>\n            <p class=\"text-3xl font-bold text-blue-600\">${employeeCount}</p>\n          </div>\n          \n          <div class=\"bg-green-50 p-4 rounded-lg\">\n            <h3 class=\"text-lg font-semibold text-green-800\">Present Today</h3>\n            <p class=\"text-3xl font-bold text-green-600\">${presentCount}</p>\n          </div>\n          \n          <div class=\"bg-red-50 p-4 rounded-lg\">\n            <h3 class=\"text-lg font-semibold text-red-800\">Absent Today</h3>\n            <p class=\"text-3xl font-bold text-red-600\">${absentCount}</p>\n          </div>\n        </div>\n\n        <div class=\"flex space-x-4\">\n          <button id=\"viewEmployeesBtn\" class=\"bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded\">\n            View Employees\n          </button>\n          <button id=\"viewAttendanceBtn\" class=\"bg-green-500 hover:bg-green-700 text-white font-bold py-2 px-4 rounded\">\n            View Attendance\n          </button>\n          <button id=\"addEmployeeBtn\" class=\"bg-purple-500 hover:bg-purple-700 text-white font-bold py-2 px-4 rounded\">\n            Add Employee\n          </button>\n        </div>\n      </div>\n    `;\n  }\n\n  renderEmployeeListView() {\n    const dashboard = document.getElementById('dashboard');\n    if (!dashboard) return;\n\n    const employeeList = this.employees.map(emp => `\n      <tr class=\"border-b\">\n        <td class=\"py-2 px-4\">${emp.id}</td>\n        <td class=\"py-2 px-4\">${emp.name}</td>\n        <td class=\"py-2 px-4\">${emp.position}</td>\n        <td class=\"py-2 px-4\">${emp.department}</td>\n        <td class=\"py-2 px-4\">${emp.email}</td>\n      </tr>\n    `).join('');\n\n    dashboard.innerHTML = `\n      <div class=\"p-6 bg-white rounded-lg shadow-md\">\n        <h2 class=\"text-2xl font-bold text-gray-800 mb-4\">Employee List</h2>\n        \n        <table class=\"min-w-full bg-white border border-gray-200\">\n          <thead>\n            <tr class=\"bg-gray-100\">\n              <th class=\"py-2 px-4 border-b text-left\">ID</th>\n              <th class=\"py-2 px-4 border-b text-left\">Name</th>\n              <th class=\"py-2 px-4 border-b text-left\">Position</th>\n              <th class=\"py-2 px-4 border-b text-left\">Department</th>\n              <th class=\"py-2 px-4 border-b text-left\">Email</th>\n            </tr>\n          </thead>\n          <tbody>\n            ${employeeList}\n          </tbody>\n        </table>\n        \n        <button id=\"backToDashboardBtn\" class=\"mt-4 bg-gray-500 hover:bg-gray-700 text-white font-bold py-2 px-4 rounded\">\n          Back to Dashboard\n        </button>\n      </div>\n    `;\n\n    document.getElementById('backToDashboardBtn')?.addEventListener('click', () => this.renderDashboard());\n  }\n\n  renderAttendanceView() {\n    const dashboard = document.getElementById('dashboard');\n    if (!dashboard) return;\n\n    const attendanceList = this.attendanceRecords.map(record => {\n      const employee = this.getEmployeeById(record.employeeId);\n      return `\n        <tr class=\"border-b\">\n          <td class=\"py-2 px-4\">${employee ? employee.name : 'Unknown'}</td>\n          <td class=\"py-2 px-4\">${record.date}</td>\n          <td class=\"py-2 px-4\">\n            <span class=\"px-2 py-1 rounded ${record.status === 'present' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}\">\n              ${record.status.charAt(0).toUpperCase() + record.status.slice(1)}\n            </span>\n          </td>\n          <td class=\"py-2 px-4\">${record.checkIn || '-'}</td>\n          <td class=\"py-2 px-4\">${record.checkOut || '-'}</td>\n        </tr>\n      `;\n    }).join('');\n\n    dashboard.innerHTML = `\n      <div class=\"p-6 bg-white rounded-lg shadow-md\">\n        <h2 class=\"text-2xl font-bold text-gray-800 mb-4\">Attendance Records</h2>\n        \n        <table class=\"min-w-full bg-white border border-gray-200\">\n          <thead>\n            <tr class=\"bg-gray-100\">\n              <th class=\"py-2 px-4 border-b text-left\">Employee</th>\n    