    "styles.css": "@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');\n\n:root {\n  --primary-color: #2563eb;\n  --primary-dark: #1d4ed8;\n  --secondary-color: #0f172a;\n  --accent-color: #8b5cf6;\n  --success-color: #10b981;\n  --warning-color: #f59e0b;\n  --error-color: #ef4444;\n  --light-color: #f8fafc;\n  --dark-color: #0f172a;\n  --gray-100: #f1f5f9;\n  --gray-200: #e2e8f0;\n  --gray-300: #cbd5e1;\n  --gray-400: #94a3b8;\n  --gray-500: #64748b;\n  --gray-600: #475569;\n  --gray-700: #334155;\n  --gray-800: #1e293b;\n  --border-radius: 8px;\n  --box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);\n  --transition: all 0.3s ease;\n}\n\n* {\n  margin: 0;\n  padding: 0;\n  box-sizing: border-box;\n}\n\nbody {\n  font-family: 'Inter', sans-serif;\n  background-color: var(--light-color);\n  color: var(--dark-color);\n  line-height: 1.6;\n}\n\n.container {\n  width: 100%;\n  max-width: 1200px;\n  margin: 0 auto;\n  padding: 0 1rem;\n}\n\n/* Header Styles */\n.header {\n  background-color: var(--secondary-color);\n  color: white;\n  padding: 1rem 0;\n  box-shadow: var(--box-shadow);\n  position: sticky;\n  top: 0;\n  z-index: 100;\n}\n\n.header-content {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n}\n\n.logo {\n  font-size: 1.5rem;\n  font-weight: 700;\n}\n\n.nav-menu {\n  display: flex;\n  list-style: none;\n  gap: 1rem;\n}\n\n.nav-link {\n  color: white;\n  text-decoration: none;\n  padding: 0.5rem 1rem;\n  border-radius: var(--border-radius);\n  transition: var(--transition);\n}\n\n.nav-link:hover {\n  background-color: rgba(255, 255, 255, 0.1);\n}\n\n/* Dashboard Grid */\n.dashboard-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));\n  gap: 1.5rem;\n  margin-top: 2rem;\n}\n\n.card {\n  background-color: white;\n  border-radius: var(--border-radius);\n  box-shadow: var(--box-shadow);\n  padding: 1.5rem;\n  transition: var(--transition);\n}\n\n.card:hover {\n  transform: translateY(-5px);\n  box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);\n}\n\n.card-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin-bottom: 1rem;\n}\n\n.card-title {\n  font-size: 1.25rem;\n  font-weight: 600;\n  color: var(--secondary-color);\n}\n\n/* Form Styles */\n.form-container {\n  background-color: white;\n  border-radius: var(--border-radius);\n  box-shadow: var(--box-shadow);\n  padding: 2rem;\n  margin-top: 2rem;\n}\n\n.form-group {\n  margin-bottom: 1.5rem;\n}\n\n.form-label {\n  display: block;\n  margin-bottom: 0.5rem;\n  font-weight: 500;\n  color: var(--secondary-color);\n}\n\n.form-input,\n.form-select,\n.form-textarea {\n  width: 100%;\n  padding: 0.75rem;\n  border: 1px solid var(--gray-300);\n  border-radius: var(--border-radius);\n  font-family: 'Inter', sans-serif;\n  font-size: 1rem;\n  transition: var(--transition);\n}\n\n.form-input:focus,\n.form-select:focus,\n.form-textarea:focus {\n  outline: none;\n  border-color: var(--primary-color);\n  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.1);\n}\n\n.form-textarea {\n  min-height: 120px;\n  resize: vertical;\n}\n\n.btn {\n  padding: 0.75rem 1.5rem;\n  border: none;\n  border-radius: var(--border-radius);\n  font-family: 'Inter', sans-serif;\n  font-size: 1rem;\n  font-weight: 500;\n  cursor: pointer;\n  transition: var(--transition);\n}\n\n.btn-primary {\n  background-color: var(--primary-color);\n  color: white;\n}\n\n.btn-primary:hover {\n  background-color: var(--primary-dark);\n}\n\n.btn-secondary {\n  background-color: var(--gray-200);\n  color: var(--secondary-color);\n}\n\n.btn-secondary:hover {\n  background-color: var(--gray-300);\n}\n\n/* Table Styles */\n.table-container {\n  background-color: white;\n  border-radius: var(--border-radius);\n  box-shadow: var(--box-shadow);\n  overflow: hidden;\n  margin-top: 2rem;\n}\n\n.table {\n  width: 100%;\n  border-collapse: collapse;\n}\n\n.table th,\n.table td {\n  padding: 1rem;\n  text-align: left;\n  border-bottom: 1px solid var(--gray-200);\n}\\n\n.table th {\n  background-color: var(--gray-100);\n  font-weight: 600;\n  color: var(--secondary-color);\n}\n\n.table tr:hover {\n  background-color: var(--gray-50);\n}\n\n/* Responsive Design */\n@media (max-width: 768px) {\n  .header-content {\n    flex-direction: column;\n    gap: 1rem;\n  }\n\n  .nav-menu {\n    flex-wrap: wrap;\n    justify-content: center;\n  }\n\n  .dashboard-grid {\n    grid-template-columns: 1fr;\n  }\n\n  .form-container {\n    padding: 1.5rem;\n  }\n\n  .table-container {\n    overflow-x: auto;\n  }\n}\n\n@media (max-width: 480px) {\n  .container {\n    padding: 0 0.5rem;\n  }\n\n  .card {\n    padding: 1rem;\n  }\n\n  .form-container {\n    padding: 1rem;\n  }\n\n  .btn {\n    width: 100%;\n    margin-bottom: 0.5rem;\n  }\n}\n\n/* Status Badges */\n.status-badge {\n  padding: 0.25rem 0.75rem;\n  border-radius: 9999px;\n  font-size: 0.875rem;\n  font-weight: 500;\n}\n\n.status-active {\n  background-color: rgba(16, 185, 129, 0.1);\n  color: var(--success-color);\n}\n\n.status-inactive {\n  background-color: rgba(239, 68, 68, 0.1);\n  color: var(--error-color);\n}\n\n.status-pending {\n  background-color: rgba(245, 158, 11, 0.1);\n  color: var(--warning-color);\n}\n\n/* Progress Bar */\n.progress-container {\n  width: 100%;\n  height: 8px;\n  background-color: var(--gray-200);\n  border-radius: 9999px;\n  overflow: hidden;\n}\n\n.progress-bar {\n  height: 100%;\n  background-color: var(--primary-color);\n  border-radius: 9999px;\n  transition: width 0.3s ease;\n}\n\n/* Alert Messages */\n.alert {\n  padding: 1rem;\n  border-radius: var(--border-radius);\n  margin-bottom: 1rem;\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n}\n\n.alert-success {\n  background-color: rgba(16, 185, 129, 0.1);\n  color: var(--success-color);\n  border-left: 4px solid var(--success-color);\n}\n\n.alert-error {\n  background-color: rgba(239, 68, 68, 0.1);\n  color: var(--error-color);\n  border-left: 4px solid var(--error-color);\n}\n\n.alert-warning {\n  background-color: rgba(245, 158, 11, 0.1);\n  color: var(--warning-color);\n  border-left: 4px solid var(--warning-color);\n}\n\n/* Pagination */\n.pagination {\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  gap: 0.5rem;\n  margin-top: 2rem;\n}\n\n.page-btn {\n  padding: 0.5rem 1rem;\n  border: 1px solid var(--gray-300);\n  background-color: white;\n  border-radius: var(--border-radius);\n  cursor: pointer;\n  transition: var(--transition);\n}\n\n.page-btn:hover {\n  background-color: var(--gray-100);\n}\n\n.page-btn.active {\n  background-color: var(--primary-color);\n  color: white;\n  border-color: var(--primary-color);\n}\n\n/* Dashboard Stats */\n.stats-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\n  gap: 1rem;\n  margin-top: 2rem;\n}\n\n.stat-card {\n  background-color: white;\n  border-radius: var(--border-radius);\n  box-shadow: var(--box-shadow);\n  padding: 1.5rem;\n  text-align: center;\n}\n\n.stat-value {\n  font-size: 2rem;\n  font-weight: 700;\n  margin-bottom: 0.5rem;\n}\n\n.stat-label {\n  color: var(--gray-600);\n  font-size: 0.875rem;\n}\n\n/* Employee Profile */\n.employee-profile {\n  display: flex;\n  gap: 2rem;\n  margin-top: 2rem;\n}\n\n.profile-avatar {\n  width: 120px;\n  height: 120px;\n  border-radius: 50%;\n  object-fit: cover;\n  border: 4px solid var(--gray-200);\n}\n\n.profile-info {\n  flex: 1;\n}\n\n.profile-name {\n  font-size: 1.5rem;\n  font-weight: 700;\n  margin-bottom: 0.5rem;\n}\n\n.profile-title {\n  color: var(--gray-600);\n  margin-bottom: 1rem;\n}\n\n.profile-details {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\n  gap: 1rem;\n}\n\n.detail-item {\n  display: flex;\n  flex-direction: column;\n}\n\n.detail-label {\n  font-size: 0.875rem;\n  color: var(--gray-500);\n}\n\n