Upstream Context:
{
  "Queen": {
    "projectGoal": "To develop a lightweight, standalone HRMS application that can be run directly from a browser using only HTML, CSS, and JavaScript without any backend dependencies.",
    "constraints": [
      "Single HTML file implementation without external dependencies",
      "Use of only browser-native technologies (HTML, CSS, JavaScript)",
      "Data persistence using localStorage API",
      "Responsive design for various screen sizes",
      "No backend server or database required"
    ]
  },
  "Planner": {
    "features": [
      {
        "id": "HRMS-FEATURE-001",
        "mvpReference": "HRMS-MVP-001",
        "name": "Employee Data Management",
        "description": "Ability to add, view, edit, and delete employee records with fields for name, position, department, contact information, and hire date.",
        "priority": "Critical"
      },
      {
        "id": "HRMS-FEATURE-002",
        "mvpReference": "HRMS-MVP-001",
        "name": "Attendance Tracking",
        "description": "Capture and store attendance records for employees with date, status (present, absent, leave), and optional notes.",
        "priority": "Critical"
      },
      {
        "id": "HRMS-FEATURE-003",
        "mvpReference": "HRMS-MVP-001",
        "name": "Reporting Dashboard",
        "description": "Display basic employee statistics including total employees, attendance summary, and department-wise breakdown.",
        "priority": "High"
      },
      {
        "id": "HRMS-FEATURE-004",
        "mvpReference": "HRMS-MVP-001",
        "name": "Responsive UI",
        "description": "Interface that adapts to different screen sizes including desktop, tablet, and mobile devices.",
        "priority": "High"
      },
      {
        "id": "HRMS-FEATURE-005",
        "mvpReference": "HRMS-MVP-001",
        "name": "Data Persistence",
        "description": "Store all employee and attendance data locally in the browser using localStorage API.",
        "priority": "Critical"
      }
    ],
    "functionalRequirements": [
      "User can add new employees with required fields",
      "User can view all employee records in a table format",
      "User can edit existing employee information",
      "User can delete employee records",
      "User can record attendance for employees with date and status",
      "User can view attendance records by employee or date range",
      "System displays dashboard showing key HR metrics",
      "Application works completely offline using browser storage",
      "Interface is responsive across different device sizes"
    ],
    "nonFunctionalRequirements": {
      "security": [
        "Data stored locally in browser with no external transmission",
        "No sensitive data handling beyond what's necessary for HR operations",
        "Client-side only implementation to prevent unauthorized access to raw data"
      ],
      "performance": [
        "Application loads and responds within 2 seconds on modern browsers",
        "Efficient rendering of employee and attendance tables",
        "Optimized data retrieval using localStorage API"
      ],
      "scalability": [
        "Designed for small to medium-sized organizations",
        "Limited by browser storage capacity constraints",
        "Single-file implementation suitable for local deployment"
      ],
      "usability": [
        "Intuitive interface with clear navigation",
        "Form validation for required fields",
        "Responsive design for all device sizes",
        "Clear visual feedback for user actions"
      ],
      "maintainability": [
        "Single HTML file structure for easy deployment",
        "Modular JavaScript code organization",
        "Comments in code for future maintenance",
        "No external dependencies to manage"
      ],
      "accessibility": [
        "Semantic HTML structure",
        "Keyboard navigation support",
        "Sufficient color contrast for readability",
        "Screen reader compatibility"
      ],
      "reliability": [
        "Data persistence using browser localStorage API",
        "Error handling for invalid inputs",
        "Graceful degradation on unsupported browsers",
        "Consistent behavior across modern browsers"
      ]
    },
    "recommendedTechStack": {
      "frontend": "HTML5, CSS3, JavaScript ES6",
      "backend": "none",
      "database": "localstorage",
      "authentication": "none",
      "deployment": "local file system",
      "additionalTechnologies": [
        "localStorage API",
        "Responsive design frameworks (mobile-first approach)"
      ]
    }
  },
  "Architect": {
    "modules": [
      {
        "id": "frontend-entry",
