  "Coder": {
    "index.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>HRMS Application</title>\n  <link href=\"https://cdn.jsdelivr.net/npm/tailwindcss@2.2.19/dist/tailwind.min.css\" rel=\"stylesheet\">\n</head>\n<body class=\"bg-gray-100\">\n  <div id=\"root\" class=\"min-h-screen flex flex-col\">\n    <!-- Header -->\n    <header class=\"bg-blue-600 text-white shadow-md\">\n      <div class=\"container mx-auto px-4 py-3 flex justify-between items-center\">\n        <h1 class=\"text-xl font-bold\">Human Resource Management System</h1>\n        <nav>\n          <ul class=\"flex space-x-4\">\n            <li><a href=\"#\" class=\"hover:underline\">Dashboard</a></li>\n            <li><a href=\"#\" class=\"hover:underline\">Employees</a></li>\n            <li><a href=\"#\" class=\"hover:underline\">Departments</a></li>\n            <li><a href=\"#\" class=\"hover:underline\">Reports</a></li>\n            <li><a href=\"#\" class=\"hover:underline\">Settings</a></li>\n          </ul>\n        </nav>\n      </div>\n    </header>\n\n    <!-- Main Content -->\n    <main class=\"flex-grow container mx-auto px-4 py-6\">\n      <div class=\"bg-white rounded-lg shadow-md p-6 mb-6\">\n        <h2 class=\"text-2xl font-semibold text-gray-800 mb-4\">Welcome to HRMS</h2>\n        <p class=\"text-gray-600 mb-4\">Manage your organization's human resources efficiently with our comprehensive HR management system.</p>\n        \n        <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4 mt-6\">\n          <div class=\"bg-blue-50 p-4 rounded-lg border border-blue-100\">\n            <h3 class=\"font-medium text-blue-800 mb-2\">Employee Management</h3>\n            <p class=\"text-sm text-gray-600\">Add, update, and manage employee records and information.</p>\n          </div>\n          \n          <div class=\"bg-green-50 p-4 rounded-lg border border-green-100\">\n            <h3 class=\"font-medium text-green-800 mb-2\">Payroll Processing</h3>\n            <p class=\"text-sm text-gray-600\">Calculate and process employee salaries and benefits.</p>\n          </div>\n          \n          <div class=\"bg-purple-50 p-4 rounded-lg border border-purple-100\">\n            <h3 class=\"font-medium text-purple-800 mb-2\">Leave Management</h3>\n            <p class=\"text-sm text-gray-600\">Track and approve employee leave requests.</p>\n          </div>\n        </div>\n      </div>\n\n      <!-- Stats Section -->\n      <div class=\"grid grid-cols-1 md:grid-cols-4 gap-4 mb-6\">\n        <div class=\"bg-white p-4 rounded-lg shadow\">\n          <p class=\"text-gray-500 text-sm\">Total Employees</p>\n          <p class=\"text-2xl font-bold\">1,248</p>\n        </div>\n        \n        <div class=\"bg-white p-4 rounded-lg shadow\">\n          <p class=\"text-gray-500 text-sm\">Active Departments</p>\n          <p class=\"text-2xl font-bold\">12</p>\n        </div>\n        \n        <div class=\"bg-white p-4 rounded-lg shadow\">\n          <p class=\"text-gray-500 text-sm\">Pending Leave Requests</p>\n          <p class=\"text-2xl font-bold\">23</p>\n        </div>\n        \n        <div class=\"bg-white p-4 rounded-lg shadow\">\n          <p class=\"text-gray-500 text-sm\">New Hires (This Month)</p>\n          <p class=\"text-2xl font-bold\">12</p>\n        </div>\n      </div>\n\n      <!-- Recent Activity -->\n      <div class=\"bg-white rounded-lg shadow-md p-6\">\n        <h3 class=\"text-lg font-semibold text-gray-800 mb-4\">Recent Activity</h3>\n        <ul class=\"space-y-3\">\n          <li class=\"flex items-start border-b pb-3\">\n            <div class=\"bg-blue-100 rounded-full p-2 mr-3\">\n              <svg xmlns=\"http://www.w3.org/2000/svg\" class=\"h-5 w-5 text-blue-600\" viewBox=\"0 0 20 20\" fill=\"currentColor\">\n                <path fill-rule=\"evenodd\" d=\"M10 18a8 8 0 100-16 8 8 0 000 16zm1-11a1 1 0 10-2 0v2H7a1 1 0 10